import{_ as a,o as t,c as l,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const L=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/VALUE-LABELS.md","filePath":"manual-en/VALUE-LABELS.md","lastUpdated":1785684581000}'),r={name:"manual-en/VALUE-LABELS.md"};function o(i,e,n,d,c,p){return t(),l("div",null,[...e[0]||(e[0]=[s(`<h3 id="_11-11-value-labels" tabindex="-1">11.11 VALUE LABELS <a class="header-anchor" href="#_11-11-value-labels" aria-label="Permalink to &quot;11.11 VALUE LABELS&quot;">​</a></h3><p>The values of a variable can be associated with an arbitrary text string. In this way, a short value can stand for a longer, more descriptive label.</p><p>Both numeric and string variables can be given labels. For string variables, the values are case-sensitive, so that, for example, a capitalized value and its lowercase variant would have to be labeled separately if both are present in the data.</p><pre><code>VALUE LABELS
        /var_list value ’label’ [value ’label’]…
</code></pre><p><code>VALUE LABELS</code> allows values of variables to be associated with labels.</p><p>To set up value labels for one or more variables, specify the variable names after a slash (‘/’), followed by a list of values and their associated labels, separated by spaces.</p><p>Value labels in output are normally broken into lines automatically. Put ‘\\n’ in a label string to force a line break at that point. The label may still be broken into lines at additional points.</p><p>Before <code>VALUE LABELS</code> is executed, any existing value labels are cleared from the variables specified. Use <code>ADD VALUE LABELS</code> (see <a href="./ADD-VALUE-LABELS">ADD VALUE LABELS</a>) to add value labels without clearing those already present.</p>`,8)])])}const u=a(r,[["render",o]]);export{L as __pageData,u as default};
